export function SecondsSinceOpen() {
  const [seconds, setSeconds] = useState(0);
  useEffect(() => {
    const timer = setInterval(() => setSeconds(seconds + 1), 1000);
    return () => clearInterval(timer);
  }, []);
  return <span>{seconds} s</span>;
}

